def _np_conv3(x, w, b):
    c, H, Wd = x.shape; o = w.shape[0]
    xp = np.pad(x, ((0, 0), (1, 1), (1, 1)))
    cols = np.stack([xp[:, i:i + H, j:j + Wd] for i in range(3) for j in range(3)], 1).reshape(c * 9, H * Wd)
    return (w.reshape(o, c * 9) @ cols).reshape(o, H, Wd) + b[:, None, None]


def _np_lsm(z):
    z = z - z.max(-1, keepdims=True)
    return z - np.log(np.exp(z).sum(-1, keepdims=True))


def _np_sig(x):
    return 1.0 / (1.0 + np.exp(-x))


class _NpOne:
    """numpy mirror of train3.Net inference (see agent3._One for the torch version and the interface)."""
    def __init__(self, blob, cfg, team=None):
        d = np.load(io.BytesIO(zlib.decompress(base64.b85decode(blob))))
        self.W = {k: d[k].astype(np.float32) for k in d.files}; self.cfg = cfg; self.tv = _team_vec(cfg, team)
        self.nb = cfg["blocks"]; self.ch = cfg["ch"]

    def _lin(self, name, x):
        return x @ self.W[name + ".weight"].T + self.W[name + ".bias"]

    def encode(self, B, G):
        G = _with_team(G, self.tv)
        W = self.W; x = np.concatenate([B[0], np.broadcast_to(G[0][:, None, None], (G.shape[1], 10, 10))], 0).astype(np.float32)
        h = np.maximum(_np_conv3(x, W["inp.weight"], W["inp.bias"]), 0)
        for k in range(self.nb):
            a = np.maximum(_np_conv3(h, W[f"body.{k}.a.weight"], W[f"body.{k}.a.bias"]), 0)
            h = np.maximum(h + _np_conv3(a, W[f"body.{k}.b.weight"], W[f"body.{k}.b.bias"]), 0)
        return h

    def units(self, h, G, ux, uy, uv):
        G = _with_team(G, self.tv); n = len(ux)
        z0 = np.concatenate([h[:, uy, ux].T, uv, np.repeat(G, n, 0)], 1)
        z = np.maximum(self._lin("unit.2", np.maximum(self._lin("unit.0", z0), 0)), 0)
        opl = _np_lsm(self._lin("u_op", z))
        q = self._lin("tq.2", np.maximum(self._lin("tq.0", z0), 0))
        tl = _np_lsm(q @ h.reshape(h.shape[0], -1) / np.sqrt(h.shape[0]))
        return opl, tl, z

    def qty(self, z, i, cls):
        oh = np.zeros(self.W["u_op.weight"].shape[0], np.float32); oh[cls] = 1
        return _np_lsm(self._lin("u_q", np.concatenate([z[i], oh])))

    def m_start(self, h, G, MS):
        G = _with_team(G, self.tv)
        pooled = np.concatenate([h.mean((1, 2)), h.max((1, 2)), G[0], MS[0]])
        ctx = np.tanh(self._lin("m_ctx.2", np.maximum(self._lin("m_ctx.0", pooled), 0)))
        return (ctx, ctx)

    def m_step(self, st, prev_t, prev_q, sl):
        W = self.W; state, ctx = st
        x = np.concatenate([W["m_tok_emb.weight"][prev_t], W["m_q_emb.weight"][prev_q], W["m_slot_emb.weight"][sl], ctx])
        gi = W["m_gru.weight_ih"] @ x + W["m_gru.bias_ih"]; gh = W["m_gru.weight_hh"] @ state + W["m_gru.bias_hh"]
        H = state.shape[0]
        r = _np_sig(gi[:H] + gh[:H]); z = _np_sig(gi[H:2 * H] + gh[H:2 * H]); nn_ = np.tanh(gi[2 * H:] + r * gh[2 * H:])
        state = (1 - z) * nn_ + z * state
        return (state, ctx), _np_lsm(self._lin("m_tok", state))

    def m_qty(self, st, tok):
        x = np.concatenate([st[0], self.W["m_tok_emb.weight"][tok]])
        return _np_lsm(self._lin("m_q.2", np.maximum(self._lin("m_q.0", x), 0)))


def _make_model(ckpt=None, team=None):
    ms = [_NpOne(b, c, team) for b, c in zip(_BLOBS, _CFGS)]
    return ms[0] if len(ms) == 1 else _Ens(ms)

_MOVES = {"NORTH": (0, -1), "SOUTH": (0, 1), "EAST": (1, 0), "WEST": (-1, 0)}
_STRUCT = {"GOOSE": "COOP", "COW": "PASTURE", "SHEEP": "PASTURE"}
_MAX_HANDS = 16
SHED_ADJ = {(4, 4), (5, 4), (4, 5), (5, 5)}


def _tile_mask(obs, p, x, y, inv, day):
    """Copy of lab/bc/export.py _tile_mask (engine _apply_unit_action semantics); PLANT/PICKUP set by caller."""
    t = obs["farms"][p]["tiles"][y][x]; m = np.zeros(len(F.UNIT_OPS), bool); inv = inv or {}
    for mv, (dx, dy) in _MOVES.items():
        m[F.UNIT_IDX[mv]] = 0 <= x + dx < 10 and 0 <= y + dy < 10
    locked = t == "LOCKED"; empty = t is None
    d = t if isinstance(t, dict) else {}
    plant = d.get("kind") == "PLANT"; animal = "animal" in d and d.get("animal") is not None
    if plant:
        age = day - int(d.get("planted_day", day)); fy = F.feat.FIRST_YIELD.get(d.get("crop"), 99)
        m[F.UNIT_IDX["WATER"]] = not d.get("watered_today")
        m[F.UNIT_IDX["HARVEST"]] = age >= fy and int(d.get("yield_units", 0)) > 0
        m[F.UNIT_IDX["FERTILIZE"]] = inv.get("FERTILIZER", 0) > 0
    if animal:
        m[F.UNIT_IDX["HARVEST"]] = int(d.get("yield_units", 0)) > 0
        m[F.UNIT_IDX["FEED"]] = (not d.get("fed_today")) and inv.get("WHEAT", 0) > 0
        m[F.UNIT_IDX["CARE"]] = not d.get("cared_today")
        m[F.UNIT_IDX["COLLECT_FERTILIZER"]] = bool(d.get("fertilizer_available"))
    m[F.UNIT_IDX["BUILD_COOP"]] = m[F.UNIT_IDX["BUILD_PASTURE"]] = empty
    m[F.UNIT_IDX["DIG"]] = (not empty) and (not locked) and (not animal)
    adj = (x, y) in SHED_ADJ
    m[F.UNIT_IDX["DROP"]] = adj and sum(inv.values()) > 0
    for it in F.ITEMS:
        has = inv.get(it, 0) > 0
        if it in _STRUCT:
            m[F.UNIT_IDX["PLACE:" + it]] = has and ((d.get("kind") == _STRUCT[it] and not animal) or adj)
        else:
            m[F.UNIT_IDX["PLACE:" + it]] = has and adj
    m[F.UNIT_IDX["PASS"]] = True
    return m, (empty and not locked), adj


def _step_toward(x, y, tx, ty):
    if tx > x: return "EAST"
    if tx < x: return "WEST"
    if ty > y: return "SOUTH"
    if ty < y: return "NORTH"
    return None


def _filler(obs, p, x, y, inv, day, claimed, shed_left):
    """Scripted fallback for a unit whose model choice was illegal (forced PASS): do useful maintenance work."""
    tiles = obs["farms"][p]["tiles"]; inv = inv or {}
    t = tiles[y][x]; d = t if isinstance(t, dict) else {}
    wheat = int(inv.get("WHEAT", 0))
    # 1) work on the current tile
    if d.get("kind") == "PLANT":
        age = day - int(d.get("planted_day", day)); fy = F.feat.FIRST_YIELD.get(d.get("crop"), 99)
        if not d.get("watered_today"): return ["WATER"]
        if age >= fy and int(d.get("yield_units", 0)) > 0: return ["HARVEST"]
    if d.get("animal"):
        if d.get("fertilizer_available"): return ["COLLECT_FERTILIZER"]
        if int(d.get("yield_units", 0)) > 0: return ["HARVEST"]
        if not d.get("fed_today") and wheat > 0: return ["FEED"]
        if not d.get("cared_today"): return ["CARE"]
    adj = (x, y) in SHED_ADJ
    products = {k: v for k, v in inv.items() if v and k not in ("WHEAT", "FERTILIZER") and k not in _STRUCT}
    if adj and products: return ["DROP"]
    # 2) scan the farm
    unfed, water, harvest, collect = [], [], [], []
    for yy in range(10):
        for xx in range(10):
            tt = tiles[yy][xx]
            if not isinstance(tt, dict) or (xx, yy) in claimed: continue
            if tt.get("animal"):
                if not tt.get("fed_today"): unfed.append((xx, yy))
                if tt.get("fertilizer_available") or int(tt.get("yield_units", 0)) > 0: collect.append((xx, yy))
            elif tt.get("kind") == "PLANT":
                if not tt.get("watered_today"): water.append((xx, yy))
                age = day - int(tt.get("planted_day", day))
                if age >= F.feat.FIRST_YIELD.get(tt.get("crop"), 99) and int(tt.get("yield_units", 0)) > 0: harvest.append((xx, yy))
    near = lambda cells: min(cells, key=lambda c: abs(c[0] - x) + abs(c[1] - y)) if cells else None
    if unfed and wheat > 0:
        c = near(unfed); claimed.add(c); return [_step_toward(x, y, *c)]
    if unfed and wheat == 0 and shed_left.get("WHEAT", 0) > 0:
        if adj:
            n = max(1, min(len(unfed), shed_left["WHEAT"])); shed_left["WHEAT"] -= n; return ["PICKUP", "WHEAT", n]
        c = near(sorted(SHED_ADJ)); return [_step_toward(x, y, *c)]
    for cells in (water, harvest, collect):
        c = near(cells)
        if c is not None:
            claimed.add(c); return [_step_toward(x, y, *c)]
    if products:
        c = near(sorted(SHED_ADJ)); m = _step_toward(x, y, *c)
        if m: return [m]
    return None


def _team_vec(cfg, team):
    teams = cfg.get("teams") or []
    if not teams:
        return None
    v = np.zeros(len(teams), np.float32); v[teams.index(team) if team in teams else 0] = 1
    return v


def _with_team(G, tv):
    return G if tv is None else np.concatenate([G, np.broadcast_to(tv, (G.shape[0], len(tv)))], 1).astype(np.float32)


# ============================== BUNDLE START (torch-free; copied verbatim into the numpy Kaggle agent) ==============
class _Ens:
    """Ensemble of _One models with identical feature config: averages log-probabilities (geometric mean)."""
    def __init__(self, members):
        self.m = members; self.cfg = members[0].cfg
        for x in members[1:]:  # unit features must match; team sets may differ (each member appends its own one-hot)
            assert (x.cfg.get("u_dim"), x.cfg.get("uext")) == (self.cfg.get("u_dim"), self.cfg.get("uext"))

    def encode(self, B, G):
        return [x.encode(B, G) for x in self.m]

    def units(self, hs, G, ux, uy, uv):
        outs = [x.units(h, G, ux, uy, uv) for x, h in zip(self.m, hs)]
        return np.mean([o[0] for o in outs], 0), np.mean([o[1] for o in outs], 0), [o[2] for o in outs]

    def qty(self, zs, i, cls):
        return np.mean([x.qty(z, i, cls) for x, z in zip(self.m, zs)], 0)

    def m_start(self, hs, G, MS):
        return [x.m_start(h, G, MS) for x, h in zip(self.m, hs)]

    def m_step(self, sts, prev_t, prev_q, sl):
        outs = [x.m_step(st, prev_t, prev_q, sl) for x, st in zip(self.m, sts)]
        return [o[0] for o in outs], np.mean([o[1] for o in outs], 0)

    def m_qty(self, sts, tok):
        return np.mean([x.m_qty(st, tok) for x, st in zip(self.m, sts)], 0)


class Agent:
    def __init__(self, ckpt, sample=False, temp=1.0, seed=12345, persist=False, dedupe=False, msample=False, fill=False,
                 smask=False, notrip=False, team=None, trustop=False):
        self.model = _make_model(ckpt, team)
        self.sample = sample; self.temp = temp; self.rng = np.random.default_rng(seed)
        self.snaps = []; self.last_step = None
        uext = self.model.cfg.get("uext")
        if uext is None:
            uext = ["motion"] if self.model.cfg.get("u_dim", F.U_DIM_V1) > F.U_DIM_V1 else []
        self.motion = "motion" in uext; self.memory = "memory" in uext; self.umem = F.UnitMemory()
        self.pos_hist = []; self.day_hist = []
        self.persist = persist; self.dedupe = dedupe; self.tgt = {}; self.tgt_day = -1; self.msample = msample; self.fill = fill; self.smask = smask; self.notrip = notrip; self.trustop = trustop
        self.stats = {"n": 0, "pass": 0, "pass_forced": 0, "at_tgt_wants_move": 0, "top_masked": 0} if os.environ.get("BC3_STATS") else None

    def _pick(self, logits, mask=None, market=False):
        z = np.asarray(logits, np.float64)
        if mask is not None:
            z = np.where(mask, z, -1e9)
        if not (self.sample or (market and self.msample)):
            return int(z.argmax())
        g = -np.log(-np.log(self.rng.random(z.shape) + 1e-20) + 1e-20)
        return int((z / self.temp + g).argmax())

    def __call__(self, obs, config=None):
        p = int(obs.get("player", 0)); step = int(obs.get("step", 0)); day = int(obs.get("day", step // 24))
        if self.last_step is None or step <= self.last_step:
            self.snaps = []; self.tgt = {}; self.pos_hist = []; self.day_hist = []; self.umem = F.UnitMemory()
        if day != self.tgt_day:
            self.tgt = {}; self.tgt_day = day
        self.last_step = step
        self.snaps.append(F.snapshot(obs, p)); self.snaps = self.snaps[-(F.LAGS + 1):]
        self.pos_hist.append(F.unit_positions(obs, p)); self.day_hist.append(day)
        self.pos_hist = self.pos_hist[-3:]; self.day_hist = self.day_hist[-3:]
        Bd = F.board3(obs, p); g = F.glob3(obs, p, F.hist_features(self.snaps))
        memf = self.umem.features(len(self.pos_hist[-1]), step, day) if self.memory else None
        ul = F.units3(obs, p, F.motion_context(self.pos_hist, self.day_hist) if self.motion else None, memf)
        priv = obs.get("private") or {}; invs = priv.get("inventories") or []
        farm = obs["farms"][p]
        if True:
            B = Bd[None].astype(np.float32); G = g[None].astype(np.float32)
            h = self.model.encode(B, G)
            acts = []
            if ul:
                ux = np.array([u[0] for u in ul], np.int64); uy = np.array([u[1] for u in ul], np.int64)
                uv = np.stack([u[2] for u in ul]).astype(np.float32)
                opl, tl, z = self.model.units(h, G, ux, uy, uv)
                seeds_left = {c: int((priv.get("seeds") or {}).get(c, 0)) for c in F.CROPS}
                shed_left = {it: int((priv.get("shed") or {}).get(it, 0)) for it in F.ITEMS}
                claimed = set()
                for i, (x, y, _v) in enumerate(ul):
                    inv = invs[i] if i < len(invs) else {}
                    mu, empty_ok, adj = _tile_mask(obs, p, x, y, inv, day)
                    for c in F.CROPS:
                        mu[F.UNIT_IDX["PLANT:" + c]] = empty_ok and seeds_left[c] > 0
                    for it in F.ITEMS:
                        mu[F.UNIT_IDX["PICKUP:" + it]] = adj and shed_left[it] > 0
                    if self.persist and i in self.tgt and self.tgt[i] != (x, y):
                        tx, ty = self.tgt[i]
                    else:
                        tlog = tl[i].copy()
                        if self.dedupe:
                            for (cx, cy) in claimed:
                                if (cx, cy) not in SHED_ADJ and (cx, cy) != (x, y):
                                    tlog[cy * 10 + cx] = -1e9
                        tgt = self._pick(tlog); tx, ty = tgt % 10, tgt // 10
                    claimed.add((tx, ty))
                    if (tx, ty) != (x, y):
                        self.tgt[i] = (tx, ty)
                    else:
                        self.tgt.pop(i, None)
                    want = np.zeros(len(F.UNIT_OPS), bool)
                    want[F.UNIT_IDX["EAST"]] = tx > x; want[F.UNIT_IDX["WEST"]] = tx < x
                    want[F.UNIT_IDX["SOUTH"]] = ty > y; want[F.UNIT_IDX["NORTH"]] = ty < y
                    mv = want & mu
                    top_op = F.UNIT_OPS[int(np.argmax(opl[i]))]
                    if (tx, ty) != (x, y) and mv.any():
                        mask = mv
                    elif self.trustop and (tx, ty) == (x, y) and top_op in _MOVES and mu[F.UNIT_IDX[top_op]]:
                        mask = mu.copy()  # target head says "here" but the op head wants to move: trust the op head
                    else:
                        mask = mu.copy()
                        for k in _MOVES:
                            mask[F.UNIT_IDX[k]] = False
                    cls = self._pick(opl[i], mask); k = F.UNIT_OPS[cls]
                    if self.stats is not None:
                        top = int(np.argmax(opl[i])); st = self.stats
                        st["n"] += 1; st["pass"] += k == "PASS"
                        st["pass_forced"] += (k == "PASS") and (F.UNIT_OPS[top] != "PASS")
                        st["at_tgt_wants_move"] += ((tx, ty) == (x, y)) and (F.UNIT_OPS[top] in _MOVES)
                        st["top_masked"] += not mask[top]
                    if self.fill and k == "PASS" and F.UNIT_OPS[int(np.argmax(opl[i]))] != "PASS":
                        fa = _filler(obs, p, x, y, inv, day, claimed, shed_left)
                        if fa is not None and fa[0] is not None:
                            acts.append(fa)
                            if self.stats is not None: self.stats["filled"] = self.stats.get("filled", 0) + 1
                            continue
                    if k.startswith("PLANT:"):
                        seeds_left[k[6:]] -= 1; acts.append(["PLANT", k[6:]])
                    elif k.startswith("PICKUP:") or k.startswith("PLACE:"):
                        ql = self.model.qty(z, i, cls)
                        n = F.QTY_VALS[self._pick(ql)]; op, it = k.split(":")
                        if op == "PICKUP":
                            n = max(1, min(n, shed_left[it])); shed_left[it] -= n
                        acts.append([op, it, n])
                    else:
                        acts.append([k])
            # market: autoregressive slot decoding
            n_hands = len(farm.get("hands") or []); hires = 0
            lands_left = max(0, 3 - (len(farm.get("unlocked_quadrants") or []) - 1)); lands = 0
            if self.memory:
                self.umem.update(acts, self.pos_hist[-1], step)
            ms = F.shed_after_units(obs, p, acts)
            sell_left = {it: int(round(v * 50)) for it, v in zip(F.ITEMS, ms)}
            MS = ms[None].astype(np.float32)
            state = self.model.m_start(h, G, MS)
            prev_t = F.N_TOK; prev_q = F.QMAX; orders = []; sold = set()
            for sl in range(F.N_SLOTS):
                state, logit = self.model.m_step(state, prev_t, prev_q, sl)
                mask = np.ones(F.N_TOK, bool)
                mask[F.TOK_IDX["HIRE"]] = n_hands + hires < _MAX_HANDS
                mask[F.TOK_IDX["BUY_LAND"]] = lands < lands_left
                if self.smask:  # SELL only what is in the shed at market time; units bought this turn are NOT sellable
                    for it in F.PRODUCTS:
                        mask[F.TOK_IDX["SELL:" + it]] = sell_left.get(it, 0) > 0
                if self.notrip:  # no intra-turn round trips: no BUY of an item already sold this turn
                    for it in ("WHEAT", "FERTILIZER"):
                        if it in sold:
                            mask[F.TOK_IDX["BUY_PRODUCT:" + it]] = False
                tok = self._pick(logit, mask, market=True); key = F.TOKENS[tok]
                if key == "END":
                    break
                if key in ("NOOP", "HIRE", "BUY_LAND"):
                    orders.append([key]); q = F.QMAX
                    hires += key == "HIRE"; lands += key == "BUY_LAND"
                else:
                    ql = self.model.m_qty(state, tok); q = self._pick(ql, market=True)
                    op, it = key.split(":"); n = q + 1
                    if op == "SELL":
                        sold.add(it)
                        if self.smask:
                            n = max(1, min(n, sell_left.get(it, 0))); sell_left[it] -= n
                    orders.append([op, it, n])
                prev_t = tok; prev_q = q
        return {"farmer": acts[0] if acts else ["PASS"], "hands": acts[1:], "market": orders}


_AG = Agent(None, **{'persist': True, 'dedupe': True, 'fill': True, 'team': 'o28_dsm_cn'})


def agent(obs, config=None):
    try:
        return _AG(obs, config)
    except Exception:
        return {"farmer": ["PASS"], "hands": [], "market": []}


# ================= HG: herd guard for the BC agent (lab/pavel, 2026-09-29) =================
# Prevents animal escapes (engine: an animal unfed on two consecutive days leaves its structure).
# 1) If an animal that was unfed yesterday is still unfed today, and the nearest unit only just has enough
#    turns left to fetch wheat (shed-adjacent PICKUP) and walk to it, that unit is overridden to feed it.
# 2) Keeps shed wheat >= herd size at the start of each day by an appended BUY_PRODUCT WHEAT (cash permitting);
#    under an urgent shortage it also drops the policy's own WHEAT sales.
_HG = {'on': True, 'active_last_day': 13, 'slack': 3, 'buy_on': True, 'stock_hours': (0, 1, 2), 'stock_frac': 1.0, 'max_buy': 30,
       'cash_keep': 0, 'last_day': 29}
_HG_STATS = {'overrides': 0, 'buy_turns': 0, 'buy_units': 0, 'dropped_sells': 0, 'errors': 0}
_HG_SHED = [(4, 4), (5, 4), (4, 5), (5, 5)]


def _hg_d(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])


def _hg_mv(x, y, tx, ty):
    if tx > x: return "EAST"
    if tx < x: return "WEST"
    if ty > y: return "SOUTH"
    if ty < y: return "NORTH"
    return "PASS"


def _hg_apply(obs, action):
    p = int(obs["player"]); step = int(obs["step"]); day = step // 24; hour = step % 24
    if step >= 718 or day > int(_HG.get("active_last_day", 29)):
        return action
    farm = obs["farms"][p]; tiles = farm["tiles"]; priv = obs.get("private") or {}
    shed = priv.get("shed") or {}; invs = priv.get("inventories") or []
    animals = [(x, y, tiles[y][x]) for y in range(10) for x in range(10)
               if isinstance(tiles[y][x], dict) and tiles[y][x].get("animal")]
    if not animals:
        return action
    pos = [tuple(farm["farmer"])] + [tuple(h) for h in (farm.get("hands") or [])]
    acts = [list(action.get("farmer") or ["PASS"])] + [list(a) for a in (action.get("hands") or [])]
    while len(acts) < len(pos):
        acts.append(["PASS"])
    carried = [int((invs[i] if i < len(invs) else {}).get("WHEAT", 0) or 0) for i in range(len(pos))]
    shed_w = int(shed.get("WHEAT", 0) or 0)
    urgent_all = [(x, y) for x, y, t in animals if int(t.get("consecutive_unfed", 0) or 0) >= 1 and not t.get("fed_today")]
    urgent = list(urgent_all)
    for i, a in enumerate(acts):
        if a and a[0] == "FEED" and pos[i] in urgent and carried[i] > 0:
            urgent.remove(pos[i]); carried[i] -= 1
    changed = False
    free = set(range(len(pos)))
    for ax, ay in urgent:
        best = None
        for i in free:
            if carried[i] > 0:
                cost = _hg_d(pos[i], (ax, ay)) + 1
            elif shed_w > 0:
                s = min(_HG_SHED, key=lambda c: (_hg_d(pos[i], c) + _hg_d(c, (ax, ay)), c))
                cost = _hg_d(pos[i], s) + 1 + _hg_d(s, (ax, ay)) + 1
            else:
                continue
            if best is None or cost < best[0]:
                best = (cost, i)
        if best is None:
            continue
        cost, i = best
        if hour + cost + int(_HG["slack"]) < 24:
            continue
        free.discard(i)
        if carried[i] > 0:
            new = ["FEED"] if pos[i] == (ax, ay) else [_hg_mv(pos[i][0], pos[i][1], ax, ay)]
            carried[i] -= 1
        elif pos[i] in _HG_SHED:
            n = max(1, min(shed_w, len(urgent))); new = ["PICKUP", "WHEAT", n]; shed_w -= n
        else:
            s = min(_HG_SHED, key=lambda c: (_hg_d(pos[i], c) + _hg_d(c, (ax, ay)), c))
            new = [_hg_mv(pos[i][0], pos[i][1], s[0], s[1])]
        if new != acts[i]:
            acts[i] = new; changed = True; _HG_STATS["overrides"] += 1
    market = [list(o) if isinstance(o, (list, tuple)) else o for o in (action.get("market") or [])]
    if _HG["buy_on"] and day <= int(_HG["last_day"]):
        have = int(shed.get("WHEAT", 0) or 0) + sum(int((iv or {}).get("WHEAT", 0) or 0) for iv in invs)
        need = 0
        if hour in _HG["stock_hours"]:
            need = int(len(animals) * float(_HG["stock_frac"]) + 0.999)
        if urgent_all:
            need = max(need, len(urgent_all))
        deficit = need - have
        if deficit > 0:
            if urgent_all and have < len(urgent_all):
                kept = []
                for o in market:
                    if isinstance(o, list) and len(o) >= 2 and o[0] == "SELL" and o[1] == "WHEAT":
                        _HG_STATS["dropped_sells"] += 1; continue
                    kept.append(o)
                market = kept
            price = max(1, int(((obs.get("market") or {}).get("prices") or {}).get("WHEAT", 30) or 30))
            money = int(float(farm.get("money", 0)))
            q = min(int(_HG["max_buy"]), deficit, max(0, (money - int(_HG["cash_keep"])) // (price + 2)))
            has_buy = [o for o in market if isinstance(o, list) and len(o) >= 3 and o[0] == "BUY_PRODUCT" and o[1] == "WHEAT"]
            if q > 0:
                if has_buy:
                    if int(has_buy[0][2]) < q:
                        has_buy[0][2] = q; _HG_STATS["buy_turns"] += 1; _HG_STATS["buy_units"] += q
                elif len(market) < 10:
                    market.insert(0, ["BUY_PRODUCT", "WHEAT", q]); _HG_STATS["buy_turns"] += 1; _HG_STATS["buy_units"] += q
            changed = True
    if not changed:
        return action
    return {"farmer": acts[0], "hands": acts[1:len(pos)], "market": market}


_HG_PARENT = agent
del agent


def agent(obs, config=None):
    action = _HG_PARENT(obs, config)
    if not _HG["on"]:
        return action
    try:
        return _hg_apply(obs, action)
    except Exception:
        _HG_STATS["errors"] += 1
        return action

agent.telemetry = _HG_STATS

_T047_ENGINE = {}
exec('CROPS = {\n    "WHEAT":      {"seed": 10, "first_yield_day": 2, "max_yield_day": 4, "interval": 0, "max_yield": 6, "ongoing": False},\n    "CARROT":     {"seed": 20, "first_yield_day": 2, "max_yield_day": 3, "interval": 0, "max_yield": 4, "ongoing": False},\n    "TOMATO":     {"seed": 50, "first_yield_day": 8, "max_yield_day": 8, "interval": 1, "max_yield": 4, "ongoing": True},\n    "STRAWBERRY": {"seed": 100, "first_yield_day": 10, "max_yield_day": 10, "interval": 2, "max_yield": 4, "ongoing": True},\n    "MELON":      {"seed": 80, "first_yield_day": 10, "max_yield_day": 12, "interval": 0, "max_yield": 6, "ongoing": False},\n}\n\nANIMALS = {\n    "GOOSE": {"cost": 300, "structure": "COOP",    "first_yield_day": 4, "interval": 1, "max_held": 4, "product": "EGG"},\n    "COW":   {"cost": 400, "structure": "PASTURE", "first_yield_day": 8, "interval": 2, "max_held": 6, "product": "MILK"},\n    "SHEEP": {"cost": 500, "structure": "PASTURE", "first_yield_day": 6, "interval": 3, "max_held": 6, "product": "WOOL"},\n}\n\nFARMER_MOVES = {\n    "NORTH": (0, -1),\n    "SOUTH": (0, 1),\n    "EAST":  (1, 0),\n    "WEST":  (-1, 0),\n}\n\ndef _shed_access_tiles(board_size):\n    """Four inner-corner tiles around the shed, in NWSE order."""\n    half = board_size // 2\n    return [(half - 1, half - 1), (half, half - 1), (half - 1, half), (half, half)]\n\ndef _is_shed_adjacent(pos, board_size):\n    return tuple(pos) in {(x, y) for (x, y) in _shed_access_tiles(board_size)}\n\ndef _new_plant(crop, day, turns_per_day):\n    cd = CROPS[crop]\n    return {\n        "kind": "PLANT",\n        "crop": crop,\n        "planted_day": day,\n        "watered_today": False,\n        "consecutive_unwatered": 1,  # planting day counts as unwatered\n        "yield_units": 0 if cd["ongoing"] else 1,\n        "max_lifespan_step": (-1 if cd["ongoing"] else (day + cd["max_yield_day"] + 1) * turns_per_day),\n        "fertilized_until_day": -1,\n    }\n\ndef _new_animal(animal, day):\n    a = ANIMALS[animal]\n    return {\n        "kind": a["structure"],\n        "animal": animal,\n        "placed_day": day,\n        "yield_units": 0,\n        "consecutive_unfed": 0,\n        "fed_today": False,\n        "cared_today": False,\n        "fertilizer_available": False,\n        "pending_care_bonus": 0,\n    }\n\ndef _farmer_position(farm, idx):\n    """idx 0 = main farmer, 1+ = hand index."""\n    if idx == 0:\n        return farm["farmer"]\n    return farm["hands"][idx - 1] if idx - 1 < len(farm["hands"]) else None\n\ndef _set_farmer_position(farm, idx, pos):\n    if idx == 0:\n        farm["farmer"] = list(pos)\n    else:\n        farm["hands"][idx - 1] = list(pos)\n\ndef _farmer_inventory(private, idx):\n    """Inventories list is [main_farmer, *hands]; grow it if idx is past the end."""\n    while len(private["inventories"]) <= idx:\n        private["inventories"].append({})\n    return private["inventories"][idx]\n\ndef _inv_add(inv, item, n=1):\n    inv[item] = inv.get(item, 0) + n\n\ndef _inv_take(inv, item, n=1):\n    if inv.get(item, 0) < n:\n        return False\n    inv[item] -= n\n    if inv[item] == 0:\n        del inv[item]\n    return True\n\ndef _apply_unit_action(farm, private, idx, action, board_size, day, turns_per_day, shed_capacity=100):\n    """Process one farmer/hand\'s action. Invalid / illegal actions are silent no-ops."""\n    if not isinstance(action, list) or not action:\n        return\n    op = action[0]\n    pos = _farmer_position(farm, idx)\n    if pos is None:\n        return\n    fx, fy = pos[0], pos[1]\n    inv = _farmer_inventory(private, idx)\n\n    if op in FARMER_MOVES:\n        dx, dy = FARMER_MOVES[op]\n        nx, ny = fx + dx, fy + dy\n        if not (0 <= nx < board_size and 0 <= ny < board_size):\n            return\n        # Movement onto LOCKED tiles is allowed: a hand can spawn on a locked\n        # shed-access tile, and blocking movement would strand it there forever.\n        # Tile operations (PLANT, WATER, etc.) still no-op on LOCKED tiles.\n        _set_farmer_position(farm, idx, (nx, ny))\n        return\n\n    if op == "PASS":\n        return\n\n    tile = farm["tiles"][fy][fx]\n\n    # Shed operations resolve before the LOCKED guard. They use the tile only as\n    # a standing position -- the shed itself is always owned -- and three of the\n    # four shed-access tiles start LOCKED, so guarding them first would make the\n    # shed unreachable from those tiles.\n    if op == "DROP":\n        if not _is_shed_adjacent((fx, fy), board_size):\n            return\n        shed = private["shed"]\n        for item, n in list(inv.items()):\n            if n <= 0:\n                del inv[item]\n                continue\n            room = max(0, shed_capacity - sum(shed.values()))\n            take = min(n, room)\n            if take > 0:\n                shed[item] = shed.get(item, 0) + take\n            del inv[item]\n        return\n\n    if op == "PICKUP":\n        if not _is_shed_adjacent((fx, fy), board_size):\n            return\n        if len(action) < 2:\n            return\n        item = action[1]\n        n = int(action[2]) if len(action) >= 3 else 1\n        if n <= 0:\n            return\n        # Seeds live in private["seeds"] and are consumed directly by PLANT;\n        # they never pass through farmer inventory or the shed.\n        available = private["shed"].get(item, 0)\n        n = min(n, available)\n        if n <= 0:\n            return\n        private["shed"][item] -= n\n        _inv_add(inv, item, n)\n        return\n\n    if op == "PLACE":\n        if len(action) < 2:\n            return\n        item = action[1]\n        # Animal placement: standing on a matching unoccupied structure. A LOCKED\n        # tile is the string "LOCKED", never a dict, so this branch cannot match\n        # there and PLACE falls through to the shed path below.\n        if (\n            item in ANIMALS\n            and isinstance(tile, dict)\n            and tile.get("kind") == ANIMALS[item]["structure"]\n            and "animal" not in tile\n        ):\n            if _inv_take(inv, item, 1):\n                farm["tiles"][fy][fx] = _new_animal(item, day)\n            return\n        # Shed drop: orthogonally adjacent to the shed; obeys shedCapacity.\n        if _is_shed_adjacent((fx, fy), board_size):\n            n = int(action[2]) if len(action) >= 3 else 1\n            if n <= 0:\n                return\n            n = min(n, inv.get(item, 0))\n            if n <= 0:\n                return\n            current = sum(private["shed"].values())\n            room = max(0, shed_capacity - current)\n            n = min(n, room)\n            if n <= 0:\n                return\n            inv[item] -= n\n            if inv[item] == 0:\n                del inv[item]\n            private["shed"][item] = private["shed"].get(item, 0) + n\n        return\n\n    # Everything below mutates the tile the unit stands on, so it requires that\n    # tile to be owned.\n    if tile == "LOCKED":\n        return\n\n    if op == "PLANT":\n        if len(action) < 2:\n            return\n        crop = action[1]\n        if crop not in CROPS:\n            return\n        if tile is not None:\n            return\n        if private["seeds"].get(crop, 0) <= 0:\n            return\n        private["seeds"][crop] -= 1\n        farm["tiles"][fy][fx] = _new_plant(crop, day, turns_per_day)\n        return\n\n    if op == "WATER":\n        if not (isinstance(tile, dict) and tile.get("kind") == "PLANT"):\n            return\n        if tile["watered_today"]:\n            return\n        tile["watered_today"] = True\n        crop_data = CROPS[tile["crop"]]\n        if not crop_data["ongoing"]:\n            age_days = day - tile["planted_day"]\n            window_start = (crop_data["max_yield_day"] + 1) // 2\n            if window_start <= age_days <= crop_data["max_yield_day"]:\n                bonus = 2 if tile["fertilized_until_day"] >= day else 1\n                tile["yield_units"] = min(crop_data["max_yield"], tile["yield_units"] + bonus)\n        return\n\n    if op == "HARVEST":\n        if not isinstance(tile, dict):\n            return\n        if tile.get("yield_units", 0) <= 0:\n            return\n        if tile.get("kind") == "PLANT":\n            crop_data = CROPS[tile["crop"]]\n            if day - tile["planted_day"] < crop_data["first_yield_day"]:\n                # Ongoing crops only accumulate yield_units after first_yield_day,\n                # so reaching here with yield_units > 0 indicates a bug.\n                if crop_data["ongoing"]:\n                    print(\n                        f"WARNING: HARVEST on immature ongoing {tile[\'crop\']} "\n                        f"(planted day {tile[\'planted_day\']}, current day {day}, "\n                        f"first_yield_day {crop_data[\'first_yield_day\']}, "\n                        f"yield_units {tile[\'yield_units\']}); should never happen"\n                    )\n                return\n            units = tile["yield_units"]\n            tile["yield_units"] = 0\n            _inv_add(inv, tile["crop"], units)\n            if not crop_data["ongoing"]:\n                farm["tiles"][fy][fx] = None\n        elif "animal" in tile:\n            units = tile["yield_units"]\n            tile["yield_units"] = 0\n            _inv_add(inv, ANIMALS[tile["animal"]]["product"], units)\n        return\n\n    if op == "FERTILIZE":\n        if not (isinstance(tile, dict) and tile.get("kind") == "PLANT"):\n            return\n        if not _inv_take(inv, "FERTILIZER", 1):\n            return\n        # Active for `day`, `day+1`, `day+2` (3 days inclusive).\n        tile["fertilized_until_day"] = max(tile.get("fertilized_until_day", -1), day + 2)\n        return\n\n    if op == "DIG":\n        if tile is None:\n            return\n        # Removes plants, weeds, empty coop/pasture. Does NOT remove a placed animal.\n        if isinstance(tile, dict) and "animal" in tile:\n            return\n        farm["tiles"][fy][fx] = None\n        return\n\n    if op == "BUILD_COOP":\n        if tile is not None:\n            return\n        farm["tiles"][fy][fx] = {"kind": "COOP"}\n        return\n\n    if op == "BUILD_PASTURE":\n        if tile is not None:\n            return\n        farm["tiles"][fy][fx] = {"kind": "PASTURE"}\n        return\n\n    if op == "FEED":\n        if not (isinstance(tile, dict) and "animal" in tile):\n            return\n        if tile["fed_today"]:\n            return\n        if not _inv_take(inv, "WHEAT", 1):\n            return\n        tile["fed_today"] = True\n        return\n\n    if op == "COLLECT_FERTILIZER":\n        if not (isinstance(tile, dict) and "animal" in tile):\n            return\n        if not tile["fertilizer_available"]:\n            return\n        tile["fertilizer_available"] = False\n        _inv_add(inv, "FERTILIZER", 1)\n        return\n\n    if op == "CARE":\n        if not (isinstance(tile, dict) and "animal" in tile):\n            return\n        if tile["cared_today"]:\n            return\n        tile["cared_today"] = True\n        return\n', _T047_ENGINE)
_T047_TERM = {}
exec('"""Default-off final-tick liquidation. No market-prefix reorder or new spending."""\nimport copy\n\nPRODUCTS = (\'WHEAT\', \'CARROT\', \'TOMATO\', \'STRAWBERRY\', \'MELON\', \'EGG\', \'MILK\', \'WOOL\', \'FERTILIZER\')\n\n\ndef post_unit_shed(obs, action, config, engine):\n    farm = copy.deepcopy(obs[\'farms\'][obs[\'player\']])\n    private = copy.deepcopy(obs[\'private\'])\n    cfg = config or {}\n    size = int(cfg.get(\'boardSize\', 10))\n    turns = int(cfg.get(\'turnsPerDay\', 24))\n    capacity = int(cfg.get(\'shedCapacity\', 100))\n    actions = [action.get(\'farmer\', [\'PASS\'])] + list(action.get(\'hands\', []))\n    # Match interpreter\'s atomic over-demand PLANT guard before sequential units.\n    demand = {}\n    for a in actions:\n        if a and a[0] == \'PLANT\' and len(a) >= 2:\n            demand[a[1]] = demand.get(a[1], 0) + 1\n    blocked = {it for it, n in demand.items() if n > private[\'seeds\'].get(it, 0)}\n    for i, a in enumerate(actions):\n        if a and a[0] == \'PLANT\' and len(a) >= 2 and a[1] in blocked:\n            a = [\'PASS\']\n        engine[\'_apply_unit_action\'](farm, private, i, a, size, int(obs[\'step\']) // turns, turns, capacity)\n    return private[\'shed\']\n\n\ndef liquidate(obs, action, config, engine, enabled=False):\n    if not enabled or int(obs[\'step\']) != 718:\n        return action\n    cfg = config or {}\n    cap = int(cfg.get(\'shedCapacity\', 100))\n    limit = int(cfg.get(\'maxMarketOrdersPerTurn\', 10))\n    orders = action.get(\'market\', [])\n    if not isinstance(orders, list) or len(orders) > limit:\n        return action\n    shed = post_unit_shed(obs, action, cfg, engine)\n    result = copy.deepcopy(action)\n    orders = result.setdefault(\'market\', [])\n    # Freeze through the last spending/unknown order: enlarged sales before a\n    # BUY/HIRE could change its fill and subsequent prefix funding/capacity.\n    boundary = -1\n    for i, order in enumerate(orders):\n        if not (isinstance(order, list) and order and order[0] in (\'SELL\', \'NOOP\')):\n            boundary = i\n    # Preserve earlier native sales when the policy schedules the same product\n    # again later. Liquidate only by enlarging its final suffix sale.\n    last_sell = {o[1]: i for i, o in enumerate(orders)\n                 if i > boundary and isinstance(o, list) and len(o) >= 3\n                 and o[0] == \'SELL\' and o[1] in PRODUCTS and int(o[2]) > 0}\n    left = {it: int(shed.get(it, 0)) for it in PRODUCTS}\n    for i, order in enumerate(orders):\n        if not isinstance(order, list) or len(order) < 3:\n            continue\n        op, it, q = order[:3]\n        if it not in left:\n            continue\n        q = max(0, int(q))\n        if op == \'BUY_PRODUCT\' and it in (\'WHEAT\', \'FERTILIZER\'):\n            # Upper bound: actual buy fill depends on the hidden opponent and\n            # simultaneous prices. Saturating SELL is safe for any actual fill.\n            left[it] = min(cap, left[it] + q)\n        elif op == \'SELL\':\n            if i == last_sell.get(it) and q > 0:\n                order[2] = max(q, left[it])\n            left[it] = max(0, left[it] - max(0, int(order[2])))\n    prices = obs.get(\'market\', {}).get(\'prices\', {})\n    missing = sorted((it for it in PRODUCTS if left[it] > 0),\n                     key=lambda it: (-left[it] * float(prices.get(it, 1)), PRODUCTS.index(it)))\n    for it in missing[:max(0, limit - len(orders))]:\n        orders.append([\'SELL\', it, left[it]])\n    return result\n', _T047_TERM)
_T047_ERRORS = {'terminal': 0}
_T047_PARENT = agent
del agent
def agent(obs, config=None):
    action = _T047_PARENT(obs, config)
    try:
        return _T047_TERM['liquidate'](obs, action, config, _T047_ENGINE, True)
    except Exception:
        _T047_ERRORS['terminal'] += 1
        return action
